const cutoff = Date.now() - 30*24*60*60*1000;
const within30 = (dateStr) => {
  if (!dateStr) return false;
  const t = new Date(dateStr).getTime();
  return Number.isFinite(t) && t >= cutoff;
};

// Fix #11: فیلتر ۳۰ روز اخیر همیشه اینجا (Code Node) به‌صورت تضمین‌شده اعمال می‌شود،
// مستقل از این‌که فیلتر سمت Data Table پشتیبانی شود یا نه.
const events = $('خواندن Events').all().map(i=>i.json).filter(e => within30(e.received_at));
const queue = $('خواندن Queue').all().map(i=>i.json).filter(j => within30(j.created_at));
const errors = $('خواندن Errors').all().map(i=>i.json).filter(e => within30(e.occurred_at));

const byStatus={}, byPlatform={}, byDate={};
for(const j of queue){
  const st=j.status||'unknown';
  byStatus[st]=(byStatus[st]||0)+1;
  const pf=j.platform||'unknown';
  byPlatform[pf]=(byPlatform[pf]||0)+1;
  const d=(j.created_at||'').slice(0,10);
  if(d){ byDate[d]=(byDate[d]||0)+1; }
}
const sent=byStatus.sent||0, failed=byStatus.failed||0, pending=byStatus.pending||0, processing=byStatus.processing||0;
const retrying = queue.filter(j=>j.status==='pending' && Number(j.attempts||0)>0).length;
const finished = sent+failed;
const successRate = finished ? Math.round(sent*10000/finished)/100 : 100;

const latencies = queue.filter(j=>j.sent_at && j.started_at).map(j=> new Date(j.sent_at)-new Date(j.started_at));
const avgLatencyMs = latencies.length ? Math.round(latencies.reduce((a,b)=>a+b,0)/latencies.length) : null;

return [{json:{
  generatedAt:new Date().toISOString(),
  windowDays: 30,
  summary:{
    totalArticles: events.length,
    totalJobs: queue.length,
    pending, processing, sent, failed, retrying,
    successRate,
    avgLatencyMs,
    openErrors: errors.filter(e=>(e.status||'open')==='open').length
  },
  byStatus, byPlatform, byDate,
  recentPublications: queue.filter(j=>j.status==='sent').slice(-20).reverse(),
  recentFailures: queue.filter(j=>j.status==='failed').slice(-20).reverse(),
  recentErrors: errors.slice(-20).reverse()
}}];

// Fix #4: Dashboard API قبلاً کاملاً بدون Authentication بود. اکنون یک Secret مستقل
// (DASHBOARD_API_SECRET) از Header الزامی است، جدا از WORDPRESS_WEBHOOK_SECRET، چون این دو
// مسیر مصرف‌کننده متفاوتی دارند (WordPress در برابر مدیر/مانیتورینگ).
const crypto = require('crypto');
const req = $input.first().json;
const headers = req.headers || {};

const provided = typeof headers['x-dashboard-api-secret'] === 'string' ? headers['x-dashboard-api-secret'] : '';
const expected = typeof $vars.DASHBOARD_API_SECRET === 'string' ? $vars.DASHBOARD_API_SECRET : '';

function timingSafeStringEqual(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  if (a.length === 0 || b.length === 0) return false;
  const bufA = Buffer.from(a, 'utf8');
  const bufB = Buffer.from(b, 'utf8');
  if (bufA.length !== bufB.length) {
    crypto.timingSafeEqual(bufA, bufA);
    return false;
  }
  return crypto.timingSafeEqual(bufA, bufB);
}

const authorized = Boolean(expected) && timingSafeStringEqual(provided, expected);
return [{json:{authorized}}];
